RAW696_SHA='6fc73b93eb9ec205808396a156f3f802e44941b01cf4a0a38194eddbcb110b3d'

class RouteControls(unittest.TestCase):
    def raw(self,name='RAW31'):
        raw=zlib.decompress(base64.b85decode(globals()[name]))
        self.assertEqual(hashlib.sha256(raw).hexdigest(),globals()[name+'_SHA'])
        return ET.fromstring(raw)
    def check(self,root,count=31,new_case=False):
        with tempfile.TemporaryDirectory() as tmp:
            path=Path(tmp)/'raw.trx';ET.ElementTree(root).write(path,encoding='utf-8')
            return worker.trx(path,count,new_case)
    def test_trx_authentic_raw31_historical_positive(self):
        self.assertEqual(self.check(self.raw())['passed'],31)
        with self.assertRaises(ValueError):self.check(self.raw(),31,True)
    def test_trx_historical935_export_missing_joins_rejected(self):
        with self.assertRaises(ValueError):self.check(self.raw('EXPORT935'),935)
    def test_trx_synthetic_new_case_exact_once(self):
        root=self.raw();ns='{http://microsoft.com/schemas/VisualStudio/TeamTest/2010}'
        row=root.find(ns+'Results')[0];row.set('testName',worker.NEW_CASE)
        definition=next(n for n in root.find(ns+'TestDefinitions') if n.get('id')==row.get('testId'))
        definition.set('name',worker.NEW_CASE)
        method=definition.find(ns+'TestMethod');cls,methodname=worker.NEW_CASE.rsplit('.',1)
        method.set('className',cls);method.set('name',methodname)
        self.assertEqual(self.check(root,31,True)['passed'],31)
    def test_trx_mutations_reject_inventories_outcomes_ids_and_joins(self):
        ns='{http://microsoft.com/schemas/VisualStudio/TeamTest/2010}'
        cases=[]
        for box in ('Results','TestDefinitions','TestEntries'):
            cases.extend([(box+' missing',lambda r,b=box:r.find(ns+b).remove(r.find(ns+b)[0])),
                          (box+' duplicate',lambda r,b=box:r.find(ns+b).append(copy.deepcopy(r.find(ns+b)[0])))])
        cases.extend([
          ('failed row/pass counters',lambda r:r.find(ns+'Results')[0].set('outcome','Failed')),
          ('duplicate test ID',lambda r:r.find(ns+'Results')[1].set('testId',r.find(ns+'Results')[0].get('testId'))),
          ('duplicate execution ID',lambda r:r.find(ns+'Results')[1].set('executionId',r.find(ns+'Results')[0].get('executionId'))),
          ('duplicate name',lambda r:r.find(ns+'Results')[1].set('testName',r.find(ns+'Results')[0].get('testName'))),
          ('execution mismatch',lambda r:r.find(ns+'TestEntries')[0].set('executionId','11111111-1111-4111-8111-111111111111')),
          ('name mismatch',lambda r:r.find(ns+'TestDefinitions')[0].set('name','wrong')),
          ('method mismatch',lambda r:r.find(ns+'TestDefinitions')[0].find(ns+'TestMethod').set('name','wrong')),
          ('entry test mismatch',lambda r:r.find(ns+'TestEntries')[0].set('testId','11111111-1111-4111-8111-111111111111')),
          ('definition test mismatch',lambda r:r.find(ns+'TestDefinitions')[0].set('id','11111111-1111-4111-8111-111111111111')),
          ('duplicate counters',lambda r:r.find(ns+'ResultSummary').append(copy.deepcopy(r.find(ns+'ResultSummary/'+ns+'Counters')))),
          ('summary failed',lambda r:r.find(ns+'ResultSummary').set('outcome','Failed')),
        ])
        for key in ('total','executed','passed','failed','error','timeout','aborted','inconclusive','passedButRunAborted','notRunnable','notExecuted','disconnected','warning','completed','inProgress','pending'):
            cases.append(('omitted '+key,lambda r,k=key:r.find(ns+'ResultSummary/'+ns+'Counters').attrib.pop(k)))
            cases.append(('wrong '+key,lambda r,k=key:r.find(ns+'ResultSummary/'+ns+'Counters').set(k,'1')))
        cases.append(('unknown failure counter',lambda r:r.find(ns+'ResultSummary/'+ns+'Counters').set('unknownFailure','0')))
        for name,mutate in cases:
            with self.subTest(name=name):
                root=self.raw();mutate(root)
                with self.assertRaises(ValueError):self.check(root)
    def test_trx_authentic_full696_closed_collision_positive(self):
        self.assertEqual(self.check(self.raw('RAW696'),696)['passed'],696)
        names=[n.get('testName') for n in self.raw('RAW696').iter('{http://microsoft.com/schemas/VisualStudio/TeamTest/2010}UnitTestResult')]
        self.assertEqual(set(worker.DUPLICATE_ROSTER),{name for name in names if names.count(name)>1})
    def test_closed_collision_source_witness(self):
        worker.duplicate_source(BACKEND)
        with tempfile.TemporaryDirectory() as tmp:
            auth=Path(tmp);p=auth/worker.DUPLICATE_SOURCE_PATH;p.parent.mkdir(parents=True);p.write_text('changed')
            with self.assertRaises(ValueError):worker.duplicate_source(auth)
    def test_trx_full696_mutations_closed_collision_and_joins(self):
        ns='{http://microsoft.com/schemas/VisualStudio/TeamTest/2010}'
        label=next(iter(worker.DUPLICATE_ROSTER))
        def rows(root):return [n for n in root.find(ns+'Results') if n.get('testName')==label]
        def definition(root,row):return next(n for n in root.find(ns+'TestDefinitions') if n.get('id')==row.get('testId'))
        def rename(root,row,name):row.set('testName',name);definition(root,row).set('name',name)
        def unknown(root):
            for row in rows(root):rename(root,row,label.replace('le','lx'))
        def wrong_count(root):
            row=rows(root)[0];rename(root,row,label.replace('le','ly'))
        def singleton(root):
            for i,row in enumerate(rows(root)[:2]):rename(root,row,label.replace('le','unique'+str(i)))
        def wrong_class(root):definition(root,rows(root)[0]).find(ns+'TestMethod').set('className','Wrong.Class')
        def wrong_method(root):definition(root,rows(root)[0]).find(ns+'TestMethod').set('name','WrongMethod')
        def duplicate_id(root):rows(root)[1].set('testId',rows(root)[0].get('testId'))
        def duplicate_execution(root):rows(root)[1].set('executionId',rows(root)[0].get('executionId'))
        def join(root):root.find(ns+'TestEntries')[0].set('executionId','11111111-1111-4111-8111-111111111111')
        def name_join(root):definition(root,rows(root)[0]).set('name','wrong')
        for name,mutate in [('unknown name',unknown),('wrong multiplicity',wrong_count),('singleton roster',singleton),('wrong class',wrong_class),('wrong method',wrong_method),('duplicate ID',duplicate_id),('duplicate execution',duplicate_execution),('entry join',join),('definition name join',name_join)]:
            with self.subTest(name=name):
                root=self.raw('RAW696');mutate(root)
                with self.assertRaises(ValueError):self.check(root,696)
    def request(self):
        now=datetime.now(timezone.utc)
        row={'issuedBy':'019fc21e-50f0-7112-834f-9fb3b35b9dfe','owner':'01a1009c-c0ad-71b2-986b-136d13d5d51f','phase':'auth-cs9-validation','base':route.BASE,'packetSeal':route.PACKET_SEAL,'leaseId':'11111111-1111-4111-8111-111111111111','issuedUtc':now.isoformat(),'expiresUtc':(now+timedelta(minutes=10)).isoformat(),'sourceCommit':route.BASE}
        env={'GITHUB_REPOSITORY':'MALIEV-Co-Ltd/Legacy.Maliev.AuthService','GITHUB_EVENT_NAME':'workflow_dispatch','GITHUB_REF':'refs/heads/main','GITHUB_RUN_ATTEMPT':'1','GITHUB_SHA':route.BASE}
        return row,env,now
    def test_fresh_exact_request_only(self):
        row,env,now=self.request();raw=json.dumps(row).encode()
        self.assertEqual(admission.validate(raw,hashlib.sha256(raw).hexdigest(),env,now),row)
        for changed in ({'GITHUB_RUN_ATTEMPT':'2'},{'GITHUB_SHA':'0'*40},{'GITHUB_REF':'refs/heads/draft'}):
            with self.assertRaises(ValueError):admission.validate(raw,hashlib.sha256(raw).hexdigest(),dict(env,**changed),now)
        with self.assertRaises(ValueError):admission.validate(raw,hashlib.sha256(raw).hexdigest(),env,now+timedelta(minutes=11))
    def test_wrong_graph_and_owner_request_refused(self):
        row,env,now=self.request()
        for key,value in (('owner','other'),('base','0'*40),('packetSeal','0'*64),('phase','financial')):
            raw=json.dumps(dict(row,**{key:value})).encode()
            with self.assertRaises(ValueError):admission.validate(raw,hashlib.sha256(raw).hexdigest(),env,now)
    def test_owner_hooks_preserve_actual_caps_and_no_financial_sdk_entry(self):
        shared=shared_source();raw=shared.capture(BACKEND/'eng/financial-iam')['hosted_owner.py']
        text=route.owner_text(raw);compile(text,'private-owner','exec')
        original=ast.parse(raw);modified=ast.parse(text)
        before={n.name:ast.dump(n) for n in original.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
        after={n.name:ast.dump(n) for n in modified.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
        for name in set(before)-{'main'}:self.assertEqual(before[name],after[name])
        self.assertNotIn('Invoke-FinancialIamQualification.ps1',text)
        self.assertIn('memory="128M" if args.stage == "proof" else "3G"',text)
        self.assertIn('runtime=180 if args.stage == "proof" else 2100',text)
    def test_real_current_main_materialization_exact_two_files(self):
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp)/'auth'
            subprocess.run(['git','clone','--no-hardlinks','--no-checkout',str(BACKEND),str(root)],check=True,capture_output=True,timeout=30)
            subprocess.run(['git','-C',str(root),'checkout','--detach',route.BASE],check=True,capture_output=True,timeout=30)
            result=route.materialize(BACKEND,root)
            self.assertEqual(result['base'],route.BASE)
            adapter=route.module(BACKEND/'eng/customer-self-identity-intake/controls/intake_adapter.py','test_cs9_adapter')
            self.assertEqual(set(result['changedPaths']),set(adapter.PATHS))
            for name in adapter.PATHS:self.assertEqual((root/name).read_bytes(),(route.packet(BACKEND)/'files'/name).read_bytes())
            with self.assertRaisesRegex(ValueError,'dirty checkout'):route.materialize(BACKEND,root)
    def test_proxy_preserves_original_caps_and_disposable_storage(self):
        shared=shared_source()
        api=shared.pure_create_api(BACKEND/'eng/financial-iam')
        image={'Id':'sha256:'+'a'*64,'Config':{'Volumes':{'/var/lib/postgresql':{}}}}
        data={'Image':'postgres:18-alpine','HostConfig':{'PortBindings':{'5432/tcp':[{'HostIp':'','HostPort':''}]}}}
        result=proxy.plan(data,'auth-financial-1-1-aaaaaaaaaaaa','fixed.slice',lambda:image,api.create_plan)
        self.assertEqual(result['HostConfig']['Memory'],768*1024**2)
        self.assertEqual(result['HostConfig']['PidsLimit'],64)
        self.assertEqual(result['HostConfig']['Tmpfs'],{'/var/lib/postgresql':'rw,noexec,nosuid,size=805306368'})
        self.assertEqual(result['Image'],image['Id'])
        self.assertNotIn('Tmpfs',data['HostConfig'])
    def test_proxy_rejects_other_images_and_persistent_overrides(self):
        shared=shared_source();api=shared.pure_create_api(BACKEND/'eng/financial-iam')
        image={'Id':'sha256:'+'a'*64,'Config':{'Volumes':{'/var/lib/postgresql':{}}}}
        for data in ({'Image':'other'},{'Image':'postgres:18-alpine','HostConfig':{'Binds':['/foreign:/data']}},{'Image':'postgres:18-alpine','HostConfig':{'Tmpfs':{'/foreign':'rw'}}}):
            with self.assertRaises(ValueError):proxy.plan(data,'auth-financial-1-1-aaaaaaaaaaaa','fixed.slice',lambda:image,api.create_plan)

def main():
    here=Path(__file__).resolve().parent
    for name in ('route.py','auth_owner.py','proxy.py','worker.py','caller.py','readback.py','admission.py','test_caller.py','test_route.py'):compile((here/name).read_bytes(),str(here/name),'exec')
    test_caller.BACKEND=BACKEND
    suite=unittest.TestSuite([unittest.defaultTestLoader.loadTestsFromModule(test_caller),unittest.defaultTestLoader.loadTestsFromTestCase(RouteControls)])
    if suite.countTestCases()!=31:raise ValueError('Exact 31 route controls required')
    result=unittest.TextTestRunner(verbosity=2).run(suite)
    if not result.wasSuccessful() or result.skipped:raise SystemExit(1)

if __name__=='__main__':main()
